void Ferreal::HelloRust::Register()
{
	static const bool bRegistered = []
	{
		static const Detail::FModuleTable ModuleTable = {&Detail::Log};
		ferreal_HelloRust_init(&ModuleTable);
		ferreal_HelloRust_Greeter_register(&Detail::Table_Greeter);
		ferreal_HelloRust_base_Notify_register(&Detail::BaseTable_Notify);
		ferreal_HelloRust_engine_register(&Detail::EngineTable);
		ferreal_HelloRust_cpp_register(FerrealCppHelloRust::Entries, sizeof(FerrealCppHelloRust::Entries) / sizeof(FerrealCppHelloRust::Entries[0]));
		return true;
	}();
	(void)bRegistered;
}

FString Ferreal::HelloRust::Shout(const FString& InText, UHelloBase* InNotifier)
{
	Register();
	return Ferreal::ToFString(ferreal_HelloRust_fn_shout(Ferreal::ToStr16(InText), Ferreal::ToObj(InNotifier)));
}

FString Ferreal::HelloRust::Poke(AActor* InActor, UPrimitiveComponent* InComponent)
{
	Register();
	return Ferreal::ToFString(ferreal_HelloRust_fn_poke(Ferreal::ToObj(InActor), Ferreal::ToObj(InComponent)));
}

FString Ferreal::HelloRust::Label(AActor* InActor, int32 InTimes)
{
	Register();
	return Ferreal::ToFString(ferreal_HelloRust_fn_label(Ferreal::ToObj(InActor), InTimes));
}

FString Ferreal::HelloRust::Hit(AActor* InActor, UPrimitiveComponent* InComponent)
{
	Register();
	return Ferreal::ToFString(ferreal_HelloRust_fn_hit(Ferreal::ToObj(InActor), Ferreal::ToObj(InComponent)));
}

FString Ferreal::HelloRust::Sweep(AActor* InActor)
{
	Register();
	return Ferreal::ToFString(ferreal_HelloRust_fn_sweep(Ferreal::ToObj(InActor)));
}

